import{c as a,Q as r,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"DemoEvolve: Overcoming Sparse Feedback in Agentic Harness Evolution with Demonstrations","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.24539","title":"DemoEvolve: Overcoming Sparse Feedback in Agentic Harness Evolution with Demonstrations","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2605.24539,"authors":["Lirong Che","Yuzhe Yang","Peiwen Lin","Chuang Wang","Xueqian Wang","Jian Su"],"pdf_path":"pdfs/2605.24539.pdf","published_date":"2026-05-23T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-23-demoevolve-sparse-feedback-harness-evolution-2605-24539.md","filePath":"research/papers/2026-05-23-demoevolve-sparse-feedback-harness-evolution-2605-24539.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-05-23-demoevolve-sparse-feedback-harness-evolution-2605-24539.md"};function n(i,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="demoevolve-overcoming-sparse-feedback-in-agentic-harness-evolution-with-demonstrations" tabindex="-1">DemoEvolve: Overcoming Sparse Feedback in Agentic Harness Evolution with Demonstrations <a class="header-anchor" href="#demoevolve-overcoming-sparse-feedback-in-agentic-harness-evolution-with-demonstrations" aria-label="Permalink to &quot;DemoEvolve: Overcoming Sparse Feedback in Agentic Harness Evolution with Demonstrations&quot;">​</a></h1><p><strong>Authors</strong>: Lirong Che, Yuzhe Yang, Peiwen Lin, Chuang Wang, Xueqian Wang, Jian Su <strong>Published</strong>: May 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.24539" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.24539</a><strong>arXiv ID</strong>: 2605.24539 <strong>Categories</strong>: Computer Science - Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.24539" target="_blank" rel="noreferrer">research/papers/pdfs/2605.24539.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The researchers address the challenge of improving frozen language-model agents through external harness modification rather than weight updates. They introduce DemoEvolve, which leverages expert demonstrations to guide the harness evolution process. In environments with sparse rewards and high variance outcomes, self-rollout evolution is misled by sparse feedback and candidate-selection noise, whereas incorporating human trajectory examples provides more stable guidance. The method proves particularly valuable in complex scenarios like the Balatro game, where tutorial-like textual knowledge alone does not yield stable improvement. By integrating demonstrations, DemoEvolve achieves more effective and auditable harness edits under constrained budgets compared to reward-only approaches, making the adaptation process more diagnosable and reliable in long-horizon stochastic settings.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>針對 frozen model 的 harness 演化（不改權重、只改 harness）在稀疏獎勵、高變異環境下的失效模式：self-rollout 演化被稀疏回饋與候選挑選噪聲誤導。</li><li>解法是引入專家示範（demonstrations）取代純 reward-only 訊號，在長程隨機環境（以 Balatro 桌遊為測試場景）中提供更穩定的演化指引。</li><li>相較純文字知識注入（tutorial-like textual knowledge），示範引導的 harness 編輯在受限預算下更「可審計」（auditable）且更可診斷。</li><li><strong>Workspace 關聯</strong>：與 <code>/autoload-evolution</code> 的閉環設計相關——本文佐證「稀疏/噪聲回饋下純自我演化不可靠」，示範式 grounding（人類軌跡）可作為未來自我改進迴圈防止 reward hacking 的參考機制。</li></ul>',8)])])}const u=a(s,[["render",n]]);export{p as __pageData,u as default};
